  const dark = mode === "dark";
  const cycle = (((seconds / p.duration + p.rest) % 1) + 1) % 1;
  const phase = TAU * cycle;
  const { sd, thread, gapWidths, knotAt } = frameGeometry(art, phase);
  const [kx, ky] = knotAt(knotPosition(p, phase));
  for (let x = 0; x < w; x++) lightX[x] = Math.exp(-((((x + 0.5) / w - kx) / p.spread) ** 2));
  const textureX = texture ? texture.xPad + p.drift * h * Math.sin(phase) * Number(p.motion === "filaments") : 0;
  const textureY = texture
    ? texture.yPad + 0.7 * p.drift * h * (Math.cos(phase) - 1) * 0.5 * Number(p.motion === "filaments")
    : 0;
  const bx = Math.floor(textureX),
    by = Math.floor(textureY);
  const fx = textureX - bx,
    fy = textureY - by;
  const softFilaments = dark ? p.tex : p.tex * 0.28;
  const ramp = RAMPS[p.ramp].density;
  const gapReach = dark ? 0.39 : 0.64;
  for (let y = 0; y < h; y++) {
    const lightY = Math.exp(-((((y + 0.5) / h - ky) / (p.spread * 1.35)) ** 2));
    const dy = y + 0.5 - ky * h;
    for (let x = 0; x < w; x++) {
      const i = y * w + x;
      const dx = x + 0.5 - kx * w;
      const light = lightX[x] * lightY;
      const offset = 4 * i;
      const distance = (thread[i] * h) / p.thread;
      const pd = Math.abs(distance);
      const seam = pd < 4 ? (dark ? 0.26 * Math.exp(-(pd ** 2) / 4.5) : 0.18 * Math.exp(-(pd ** 2) / 1.7)) : 0;
      const radius = (dx * dx + dy * dy) / (p.knotr * p.knotr);
      const knot = radius < 5 ? Math.max(Math.exp(-(radius ** 2)), dark ? 0.29 * Math.exp(-radius / 1.7) : 0) : 0;
      tones[offset + 1] = 256 * Math.max(seam * (0.76 + 0.24 * light), knot);
      tones[offset + 2] = sd[i];
      tones[offset + 3] = clamp(distance, -4, 4);
      tones[offset] = 0;
      if (sd[i] <= 0) continue;
      const gap = gapWidths?.[i];
      const reach = gap ? Math.min(p.reach, gap * gapReach) : p.reach;
      const r = sd[i] / reach;
      if (r >= 1) continue;
      let tone = ramp(r);
      if (texture && tone > 0) {
        const j = (y + by) * texture.stride + x + bx;
        const dots = texture.data;
        const ridgeTone =
          p.motion === "filaments"
            ? mix(mix(dots[j], dots[j + 1], fx), mix(dots[j + texture.stride], dots[j + texture.stride + 1], fx), fy)
            : dots[j];
        const band = smooth(0.025, 0.23, r) * (1 - smooth(0.62, 0.96, r));
        tone = clamp(tone + softFilaments * band * (0.66 * ridgeTone - 0.24));
      }
      if (p.levels.length) tone *= (p.levels.find(([end]) => r < end) ?? p.levels.at(-1)!)[1];
      const hold = smooth(0, LIGHT.hold, r);
      const density = dark
        ? tone * DARK_CAP * hold * (LIGHT.low + (1 - LIGHT.low) * light)
        : tone * (1 - hold * (LIGHT.shade * light - LIGHT.dim * (1 - light)));
      tones[offset] = 256 * clamp(density);
    }
  }
  return tones;
}

const inStock = (distance: number) => distance > 0;
const inSolid = (distance: number) => distance <= 0;

// Flood stock from the frame. Separate solid islands are allowed, as in ROI.
function checkBoundaries(distance: Float32Array, w: number, h: number, edge: Shape) {
  if (graph(edge)) {
    // Each column is monotone, so stock and solid both open vertically.
    const top = distance.subarray(0, w);
    const bottom = distance.subarray(distance.length - w);
    if ((top.some(inStock) || bottom.some(inStock)) && (top.some(inSolid) || bottom.some(inSolid))) return;
    throw new Error("the solid must meet the frame and leave room for stock");
  }

  let solidAtFrame = false;
  let stock = 0;
  let head = 0;
  let tail = 0;
  const seen = new Uint8Array(distance.length);
  const queue = new Uint32Array(distance.length);
  function visit(i: number) {
    if (!seen[i] && inStock(distance[i])) {
      seen[i] = 1;
      queue[tail++] = i;
    }
  }

  for (let i = 0; i < distance.length; i++) {
    const empty = distance[i] > 0;
    if (empty) stock++;
    if (i < w || i >= distance.length - w || i % w === 0 || i % w === w - 1) {
      if (empty) visit(i);
      else solidAtFrame = true;
    }
  }
  if (!solidAtFrame || !stock) throw new Error("the solid must meet the frame and leave room for stock");
  while (head < tail) {
    const i = queue[head++];
    const left = i % w > 0;
    const right = i % w < w - 1;
    if (left) visit(i - 1);
    if (right) visit(i + 1);
    // Stock can meet between diagonal solid cells at a rasterized edge.
    if (i >= w) {
      visit(i - w);
      if (left) visit(i - w - 1);
      if (right) visit(i - w + 1);
    }
    if (i < distance.length - w) {
      visit(i + w);
      if (left) visit(i + w - 1);
      if (right) visit(i + w + 1);
    }
  }
  if (tail === stock) return;
  // A vector edge can leave subcell flecks at a join when sampled on the screen grid.
  // Mask cells are exact, so even a single enclosed stock cell is an error.
  const tolerance = edge === "mask" ? 0 : 0.5 / h;
  if (distance.some((d, i) => !seen[i] && d > tolerance)) {
    throw new Error("the solid encloses stock; open the pocket to the frame");
  }
  for (let i = 0; i < distance.length; i++) {
    if (!seen[i] && inStock(distance[i])) distance[i] = 0;
  }
}

import { fieldScreen, paint, prepare, type FieldArt, type FieldMask } from "@/components/superthread/lib/field-core";
import { canvasRaster, packedInks, type DotScreen } from "@/components/superthread/lib/dot-screen";
import { readScreenInks } from "@/components/superthread/lib/screen-core";
// @mk/field-art 2.16.0

const FPS = 24;

export function mountField(host: HTMLElement, mask?: FieldMask) {
  const doc = host.ownerDocument;
  const view = doc.defaultView;
  if (!view) return;
  const win = view;
  const canvas = doc.createElement("canvas");
  const ctx = canvas.getContext("2d");
  const probe = doc.createElement("canvas").getContext("2d", { willReadFrequently: true });
  if (!ctx || !probe) return;
  const context = ctx;
  const inkProbe = probe;
  canvas.setAttribute("aria-hidden", "true");
  Object.assign(canvas.style, { position: "absolute", imageRendering: "pixelated", pointerEvents: "none" });
  host.append(canvas);

  const motion = win.matchMedia("(prefers-reduced-motion: reduce)");
  const print = win.matchMedia("print");
  let reduced = motion.matches;
  let printing = print.matches;
  let visible = false;
  let animation: number | undefined;
  let last: number | undefined;
  let elapsed = 0;
  let frame = 0;
  let destroy = false;
  let art: FieldArt | undefined;
  let image: ImageData;
  let pixels: Uint32Array;
  let screen: DotScreen;
  let palette: Uint32Array;
  let ratio: number;
  let inks: ReturnType<typeof readScreenInks>;
  let line: string;
  let resolution: MediaQueryList;

  function draw(index: number) {
    if (!art) return;
    paint(art, inks.dark ? "dark" : "light", (index % (FPS * art.spec.duration)) / FPS, pixels, screen, palette);
    context.putImageData(image, 0, 0);
  }

  function canAnimate() {
    return (
      !destroy &&
      art &&
      art.spec.motion !== "still" &&
      host.hasAttribute("data-field-art-play") &&
      visible &&
      !doc.hidden &&
      !reduced &&
      !printing
    );
  }

  function tick(now: number) {
    animation = undefined;
    if (!canAnimate()) {
      last = undefined;
      return;
    }
    if (last !== undefined) elapsed += now - last;
    last = now;
    const next = Math.floor((elapsed * FPS) / 1000);
    if (next !== frame) {
      frame = next;
      draw(frame);
    }
    update();
  }

  function update() {
    if (canAnimate()) {
      animation ??= win.requestAnimationFrame(tick);
    } else {
      if (animation !== undefined) win.cancelAnimationFrame(animation);
      animation = last = undefined;
    }
  }

  function repaint() {
    if (destroy) return;
    const box = host.getBoundingClientRect();
    if (!box.width || !box.height) {
      art = undefined;
      update();
      return;
    }
    const dpr = win.devicePixelRatio;
    const { left, top, width, height, cssWidth, cssHeight } = canvasRaster(box, dpr);
    const spec = host.dataset.fieldArt ?? "";
    inks = readScreenInks(win.getComputedStyle(host), inkProbe);
    palette = packedInks([undefined, inks.screen, inks.thread, inks.solid]);

    const w = Math.max(2, Math.round(cssWidth));
    const h = Math.max(2, Math.round(cssHeight));
    if (
      !art ||
      art.width !== w ||
      art.height !== h ||
      line !== spec ||
      ratio !== dpr ||
      screen.width !== width ||
      screen.height !== height
    ) {
      if (!art || art.width !== w || art.height !== h || line !== spec) {
        art = prepare(spec, w, h, { mask });
      }
      if (line !== spec) elapsed = frame = 0;
      line = spec;
      ratio = dpr;
      screen = fieldScreen(art, dpr, width, height);
      canvas.width = width;
      canvas.height = height;
      image = context.createImageData(width, height);
      pixels = new Uint32Array(image.data.buffer);
    }
    Object.assign(canvas.style, {
      left: `${left}px`,
      top: `${top}px`,
      width: `${cssWidth}px`,
      height: `${cssHeight}px`,
    });
    draw(reduced || printing ? 0 : frame);
    update();
  }

  function watchResolution() {
    resolution?.removeEventListener("change", watchResolution);
    resolution = win.matchMedia(`(resolution: ${win.devicePixelRatio}dppx)`);
    resolution.addEventListener("change", watchResolution);
    repaint();
  }
  const motionChanged = (event: MediaQueryListEvent) => {
    reduced = event.matches;
    draw(reduced || printing ? 0 : frame);
    update();
  };
  const beforePrint = () => {
    printing = true;
    repaint();
  };
  const afterPrint = () => {
    printing = false;
    repaint();
  };
  const printChanged = () => (print.matches ? beforePrint() : afterPrint());

  // Prepare before subscribing so a malformed spec leaves no observer or canvas behind.
  try {
    watchResolution();
  } catch (error) {
    resolution!.removeEventListener("change", watchResolution);
    canvas.remove();
    throw error;
  }

  const resize = new win.ResizeObserver(repaint);
  resize.observe(host);
  const scope = new win.MutationObserver((changes) => {
    if (changes.some(({ attributeName }) => attributeName !== "data-field-art-play")) repaint();
    else update();
  });
  for (let element: HTMLElement | null = host; element; element = element.parentElement) {
    scope.observe(element, {
      attributes: true,
      attributeFilter: ["class", "style", "data-theme", "data-field-art", "data-field-art-play"],
    });
  }
  const intersection = new win.IntersectionObserver(([entry]) => {
    visible = entry!.isIntersecting;
    update();
  });
  intersection.observe(host);
  doc.addEventListener("visibilitychange", update);
  motion.addEventListener("change", motionChanged);
  print.addEventListener("change", printChanged);
  win.addEventListener("beforeprint", beforePrint);
  win.addEventListener("afterprint", afterPrint);

  return () => {
    destroy = true;
    update();
    resize.disconnect();
    scope.disconnect();
    intersection.disconnect();
    resolution.removeEventListener("change", watchResolution);
    doc.removeEventListener("visibilitychange", update);
    motion.removeEventListener("change", motionChanged);
    print.removeEventListener("change", printChanged);
    win.removeEventListener("beforeprint", beforePrint);
    win.removeEventListener("afterprint", afterPrint);
    canvas.remove();
  };
}

